DROP TABLE IF EXISTS `core_coderule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `core_coderule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `code` varchar(64) NOT NULL,
  `name` varchar(128) NOT NULL,
  `pattern` varchar(128) NOT NULL,
  `reset_period` varchar(16) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `remark` longtext NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `core_coderule_created_at_3964ac4e` (`created_at`),
  KEY `core_coderule_created_by_id_1588575e_fk_identity_user_id` (`created_by_id`),
  KEY `core_coderule_updated_by_id_1af37077_fk_identity_user_id` (`updated_by_id`),
  CONSTRAINT `core_coderule_created_by_id_1588575e_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `core_coderule_updated_by_id_1af37077_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `core_coderule_chk_1` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
