CREATE TABLE `crm_customer` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `code` varchar(32) NOT NULL,
  `name` varchar(128) NOT NULL,
  `short_name` varchar(64) NOT NULL,
  `category` varchar(16) NOT NULL,
  `level` varchar(8) NOT NULL,
  `status` varchar(16) NOT NULL,
  `credit_limit` decimal(20,4) NOT NULL,
  `payment_terms` varchar(64) NOT NULL,
  `tax_no` varchar(32) NOT NULL,
  `address` varchar(255) NOT NULL,
  `primary_contact_name` varchar(64) NOT NULL,
  `primary_contact_phone` varchar(32) NOT NULL,
  `tags` json NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `remark` longtext NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `salesman_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_customer_company_code` (`company_id`,`code`),
  KEY `crm_customer_created_by_id_7644960d_fk_identity_user_id` (`created_by_id`),
  KEY `crm_customer_salesman_id_d8d97b6a_fk_factory_employee_id` (`salesman_id`),
  KEY `crm_customer_updated_by_id_ca46cd36_fk_identity_user_id` (`updated_by_id`),
  KEY `crm_customer_created_at_c98e1a2b` (`created_at`),
  KEY `crm_customer_status_ca528281` (`status`),
  KEY `crm_customer_is_active_4925b819` (`is_active`),
  CONSTRAINT `crm_customer_company_id_41cc014c_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `crm_customer_created_by_id_7644960d_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `crm_customer_salesman_id_d8d97b6a_fk_factory_employee_id` FOREIGN KEY (`salesman_id`) REFERENCES `factory_employee` (`id`),
  CONSTRAINT `crm_customer_updated_by_id_ca46cd36_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `ck_customer_credit_limit_non_negative` CHECK ((`credit_limit` >= 0)),
  CONSTRAINT `crm_customer_chk_1` CHECK ((`version` >= 0))
