INSERT INTO `crm_customercomplaint` VALUES (16,'2026-08-29 02:30:00.000000','2026-09-22 06:50:07.673247',0,'XJ-CP-0001','quality','important','closed','online','长绒棉T恤袖口线头多且领口偏大','客户收到 180 件订单后反馈：约 20 件袖口线头未修剪，5 件领口比样衣偏大 1cm。','2026-08-29 02:30:00.000000','陈曦','13800002005','','2026-08-30 01:00:00.000000','2026-08-31 07:00:00.000000','2026-09-01 03:00:00.000000','调整排产与物流商，后续订单预留 2 天缓冲期并每周同步进度。',5,'演示数据（新疆意尚智造）',5,NULL,15,71,69,NULL),(17,'2026-07-22 02:30:00.000000','2026-09-22 06:50:07.678981',0,'XJ-CP-0002','delivery','general','closed','phone','工装夹克交期延后 3 天','客户反映原定 3 月 18 日到货的工装夹克实际 3 月 21 日到达，影响其门店上架计划。','2026-07-22 02:30:00.000000','石建国','13800002001','','2026-07-23 01:00:00.000000','2026-07-24 07:00:00.000000','2026-07-25 03:00:00.000000','更换防潮包装并加托盘缠膜，运输合同增加防雨条款。',5,'演示数据（新疆意尚智造）',5,NULL,12,71,69,NULL),(18,'2026-08-13 02:30:00.000000','2026-09-22 06:50:07.682659',0,'XJ-CP-0003','packaging','general','resolved','email','外箱受潮导致纸箱变形','公路运输途中遇雨，外箱部分受潮变形，客户要求后续加防潮包装。','2026-08-13 02:30:00.000000','周俊','13800002004','','2026-08-14 01:00:00.000000','2026-08-15 07:00:00.000000',NULL,'调整排产与物流商，后续订单预留 2 天缓冲期并每周同步进度。',4,'演示数据（新疆意尚智造）',5,NULL,14,71,69,NULL),(19,'2026-09-10 02:30:00.000000','2026-09-22 06:50:07.684661',0,'XJ-CP-0004','price','general','handling','salesman','促销批次结算单价与报价不一致','客户对 5 月促销批次的结算单价提出异议，认为与季度报价单不符。','2026-09-10 02:30:00.000000','阿卜都拉·热合曼','13800002006','','2026-09-11 01:00:00.000000',NULL,NULL,'已受理并通知质量与仓储复核，24 小时内给出处理方案。',0,'演示数据（新疆意尚智造）',5,NULL,16,71,69,NULL),(20,'2026-09-18 02:30:00.000000','2026-09-22 06:50:07.685661',0,'XJ-CP-0005','service','severe','pending','visit','售后换货响应慢','客户反馈换货申请提交后 5 个工作日仍未收到处理结果，影响其二批订单信心。','2026-09-18 02:30:00.000000','王强','13800002003','',NULL,NULL,NULL,'',0,'演示数据（新疆意尚智造）',5,NULL,13,NULL,69,NULL);
