INSERT INTO `crm_productreview` VALUES (19,'2026-09-04 12:00:00.000000','2026-09-22 06:50:07.692912',0,'XJ-RV-0001','女士圆领长袖T恤 白色 M 160/80A',5,'closed','陈曦','2026-09-04','面料很舒服，新疆长绒棉确实亲肤，做工也不错。','感谢支持！尺码建议已更新到商品页，欢迎继续监督。','2026-09-05 02:00:00.000000','2026-09-06 01:30:00.000000','演示数据（新疆意尚智造）',5,NULL,15,69,98,NULL),(20,'2026-09-06 12:00:00.000000','2026-09-22 06:50:07.699875',0,'XJ-RV-0002','女士圆领长袖T恤 白色 L 165/84A',4,'closed','陈曦','2026-09-06','版型偏大一点，建议按平时尺码买小一码。','感谢反馈！已同步生产与质检部门持续改进缝制工艺。','2026-09-07 02:00:00.000000','2026-09-08 01:30:00.000000','演示数据（新疆意尚智造）',5,NULL,15,69,99,NULL),(21,'2026-08-20 12:00:00.000000','2026-09-22 06:50:07.704124',0,'XJ-RV-0003','男士工装夹克 藏青 175/92A',5,'replied','王强','2026-08-20','工装夹克耐磨，口袋设计实用，车间穿着很合适。','非常抱歉给您带来不便，售后已与您联系安排换货。','2026-08-21 02:00:00.000000',NULL,'演示数据（新疆意尚智造）',5,NULL,13,69,126,NULL),(22,'2026-08-26 12:00:00.000000','2026-09-22 06:50:07.709314',0,'XJ-RV-0004','女士连帽卫衣 浅灰 L 165/84A',3,'replied','周俊','2026-08-26','卫衣手感好，但帽绳偏短，希望改进。','非常抱歉给您带来不便，售后已与您联系安排换货。','2026-08-27 02:00:00.000000',NULL,'演示数据（新疆意尚智造）',5,NULL,14,69,114,NULL),(23,'2026-09-16 12:00:00.000000','2026-09-22 06:50:07.712334',0,'XJ-RV-0005','男士工装夹克 卡其 180/96A',4,'pending','阿卜都拉·热合曼','2026-09-16','整体满意，交货稍慢，希望旺季提前排产。','',NULL,NULL,'演示数据（新疆意尚智造）',5,NULL,16,NULL,130,NULL),(24,'2026-09-19 12:00:00.000000','2026-09-22 06:50:07.715340',0,'XJ-RV-0006','男士饶领短袖T恤 黑色 175/92A',2,'pending','石建国','2026-09-19','两件成衣下摆线迹不齐，已联系售后换货。','',NULL,NULL,'演示数据（新疆意尚智造）',5,NULL,12,NULL,138,NULL);
