--
-- Table structure for table `ehs_accidentrecord`
--

DROP TABLE IF EXISTS `ehs_accidentrecord`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ehs_accidentrecord` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `accident_no` varchar(32) NOT NULL,
  `title` varchar(128) NOT NULL,
  `category` varchar(16) NOT NULL,
  `level` varchar(16) NOT NULL,
  `occurred_at` datetime(6) NOT NULL,
  `location` varchar(128) NOT NULL,
  `injured_count` int(10) unsigned NOT NULL,
  `lost_days` int(10) unsigned NOT NULL,
  `loss_amount` decimal(20,6) NOT NULL,
  `description` longtext NOT NULL,
  `causes` longtext NOT NULL,
  `measures` longtext NOT NULL,
  `reported_at` datetime(6) DEFAULT NULL,
  `investigation_result` longtext NOT NULL,
  `status` varchar(16) NOT NULL,
  `closed_date` date DEFAULT NULL,
  `remark` longtext NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `department_id` bigint(20) DEFAULT NULL,
  `investigator_id` bigint(20) DEFAULT NULL,
  `reporter_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_accident_record_company_no` (`company_id`,`accident_no`),
