DROP TABLE IF EXISTS `ems_energythreshold`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ems_energythreshold` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `name` varchar(64) NOT NULL,
  `medium` varchar(16) NOT NULL,
  `upper_limit` decimal(20,6) DEFAULT NULL,
  `lower_limit` decimal(20,6) DEFAULT NULL,
  `daily_limit` decimal(20,6) DEFAULT NULL,
  `unit_consumption_limit` decimal(20,6) DEFAULT NULL,
  `offline_minutes` int(10) unsigned NOT NULL,
  `alarm_level` varchar(16) NOT NULL,
  `remark` longtext NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `meter_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_energy_threshold_company_name` (`company_id`,`name`),
  KEY `ems_energythreshold_created_by_id_d2cc2448_fk_identity_user_id` (`created_by_id`),
  KEY `ems_energythreshold_meter_id_312ebaa1_fk_ems_energymeter_id` (`meter_id`),
  KEY `ems_energythreshold_updated_by_id_2a3928d7_fk_identity_user_id` (`updated_by_id`),
  KEY `ems_energythreshold_created_at_82095583` (`created_at`),
  KEY `ems_energythreshold_medium_22096f67` (`medium`),
  KEY `ems_energythreshold_is_active_7b2c0964` (`is_active`),
  CONSTRAINT `ems_energythreshold_company_id_e9841b88_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `ems_energythreshold_created_by_id_d2cc2448_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `ems_energythreshold_meter_id_312ebaa1_fk_ems_energymeter_id` FOREIGN KEY (`meter_id`) REFERENCES `ems_energymeter` (`id`),
  CONSTRAINT `ems_energythreshold_updated_by_id_2a3928d7_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `ck_energy_threshold_offline_non_negative` CHECK ((`offline_minutes` >= 0)),
  CONSTRAINT `ems_energythreshold_chk_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ems_energythreshold_chk_2` CHECK ((`offline_minutes` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
