  KEY `equipment_inspectiontask_created_at_f7f449d3` (`created_at`),
  KEY `equipment_inspectiontask_task_type_38a51780` (`task_type`),
  KEY `equipment_inspectiontask_plan_date_27e3827a` (`plan_date`),
  KEY `equipment_inspectiontask_status_365bde30` (`status`),
  CONSTRAINT `equipment_inspection_assignee_id_d13180ad_fk_factory_e` FOREIGN KEY (`assignee_id`) REFERENCES `factory_employee` (`id`),
  CONSTRAINT `equipment_inspection_company_id_8a796a32_fk_factory_c` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `equipment_inspection_created_by_id_ca59df91_fk_identity_` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `equipment_inspection_equipment_id_c132a813_fk_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipment_equipment` (`id`),
  CONSTRAINT `equipment_inspection_updated_by_id_ffe21293_fk_identity_` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
