  `created_by_id` bigint(20) DEFAULT NULL,
  `equipment_id` bigint(20) NOT NULL,
  `item_id` bigint(20) DEFAULT NULL,
  `plan_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_maintenance_task_company_no` (`company_id`,`task_no`),
  UNIQUE KEY `uq_maintenance_task_plan_date` (`plan_id`,`plan_date`),
  KEY `idx_maint_task_status` (`company_id`,`status`),
