DROP TABLE IF EXISTS `equipment_repairrecord`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `equipment_repairrecord` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `record_no` varchar(32) NOT NULL,
  `repair_date` date NOT NULL,
  `fault_reason` longtext NOT NULL,
  `solution` longtext NOT NULL,
  `parts_used` longtext NOT NULL,
  `cost` decimal(20,4) NOT NULL,
  `downtime_minutes` int(10) unsigned NOT NULL,
  `result` longtext NOT NULL,
  `remark` longtext NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `equipment_id` bigint(20) NOT NULL,
  `repairer_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  `task_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_repair_record_company_no` (`company_id`,`record_no`),
  KEY `equipment_repairreco_created_by_id_0edf4a05_fk_identity_` (`created_by_id`),
  KEY `equipment_repairreco_equipment_id_0b31e536_fk_equipment` (`equipment_id`),
  KEY `equipment_repairreco_repairer_id_1d6387ea_fk_factory_e` (`repairer_id`),
  KEY `equipment_repairreco_updated_by_id_85998aee_fk_identity_` (`updated_by_id`),
  KEY `equipment_repairreco_task_id_609616ca_fk_equipment` (`task_id`),
  KEY `equipment_repairrecord_created_at_e7be3bc5` (`created_at`),
  KEY `equipment_repairrecord_repair_date_7ef7a754` (`repair_date`),
  CONSTRAINT `equipment_repairreco_created_by_id_0edf4a05_fk_identity_` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
