CREATE TABLE `identity_role` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `name` varchar(64) NOT NULL,
  `data_scope_type` varchar(16) NOT NULL,
  `is_system` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `sort_order` int(11) NOT NULL,
  `remark` longtext NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `company_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `identity_role_company_id_7a9ef533_fk_factory_company_id` (`company_id`),
  KEY `identity_role_is_active_4c0cdbdb` (`is_active`),
  CONSTRAINT `identity_role_company_id_7a9ef533_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
