INSERT INTO `identity_role` VALUES (1,'super_admin','超级管理员','all',1,1,1,'拥有全部权限，覆盖所有数据范围。','2026-09-17 03:41:19.178449','2026-09-22 06:47:20.142446',5),(2,'platform_admin','平台管理员','company',1,1,10,'用户、角色、字典、编码规则、审计与审批模板维护。','2026-09-17 03:41:19.188141','2026-09-22 06:47:20.154829',5),(3,'masterdata_admin','主数据管理员','company',1,1,20,'物料、款式、颜色、尺码、SKU 与标识维护。','2026-09-17 03:41:19.194724','2026-09-22 06:47:20.158832',5),(4,'factory_admin','工厂与组织管理员','company',1,1,21,'公司、部门、工厂、车间、线体、工位、员工、班次与班组维护。','2026-09-17 03:41:19.200829','2026-09-22 06:47:20.163243',5),(5,'warehouse_admin','仓储管理员','warehouse',1,1,22,'仓库、库区与储位维护；数据范围限定为被授权仓库。','2026-09-17 03:41:19.208349','2026-09-22 06:47:20.166913',5),(6,'approver','审批人','department',1,1,30,'参与审批流转，数据范围限定为本人所属部门。','2026-09-17 03:41:19.213349','2026-09-22 06:47:20.223591',5),(7,'viewer','只读用户','company',1,1,90,'仅具备查询类权限，不具备任何写入权限。','2026-09-17 03:41:19.217861','2026-09-22 06:47:20.226773',5),(8,'demo_dept_manager','部门主管（演示）','department',0,1,200,'','2026-09-17 03:43:29.376986','2026-09-18 06:36:13.507464',5),(9,'demo_gm','总经理（演示）','company',0,1,200,'','2026-09-17 03:43:29.383501','2026-09-18 06:36:13.514975',5),(10,'demo_finance','财务复核（演示）','company',0,1,200,'','2026-09-17 03:43:29.389594','2026-09-18 06:36:13.520483',5),(11,'crm_admin','客户管理员','company',1,1,23,'客户档案、联系人、客户投诉与产品评价的登记与处理。','2026-09-17 04:51:38.892397','2026-09-22 06:47:20.170050',5),(12,'srm_admin','供应商管理员','company',1,1,24,'供应商档案、联系人、资质与五维量化评价维护。准入审批复用 workflow 审批体系。','2026-09-17 04:51:38.898502','2026-09-22 06:47:20.172632',5),(13,'procurement_admin','采购管理员','company',1,1,25,'采购申请、采购订单与收货过账；来料检验判定由质检角色执行。','2026-09-17 07:17:17.598369','2026-09-22 06:47:20.177683',5),(14,'quality_inspector','质检员','company',1,1,26,'来料检验与销售退货检验判定，检验项目 / 检验单 / 质量报警 / 质量问题知识库维护；质量放行必须走库存服务 wms.quality.release。','2026-09-17 07:17:17.603171','2026-09-22 06:47:20.181867',5),(15,'sales_admin','销售管理员','company',1,1,27,'销售订单、库存占用与发货出库；退货检验判定由质检角色执行。','2026-09-17 08:57:22.418722','2026-09-22 06:47:20.189709',5),(16,'planning_admin','计划管理员','company',1,1,28,'BOM、工艺路线与 MRP 运算；采购建议转单只生成草稿采购申请，BOM / 工艺 / 采购申请审批由审批人执行。','2026-09-18 01:47:42.841505','2026-09-22 06:47:20.194035',5),(17,'equipment_admin','设备管理员','company',1,1,29,'设备台账、零部件与备品备件、保养、维修、点巡检与异常处理；备件采购申请走采购审批。','2026-09-21 08:41:56.672386','2026-09-22 06:47:20.204900',NULL),(18,'ems_admin','能源管理员','company',1,1,31,'计量区域与仪表、水电气液价格与阈值、抄表、运行记录、报警与能耗报表。','2026-09-21 08:41:56.681644','2026-09-22 06:47:20.209178',NULL),(19,'logistics_admin','厂内物流管理员','company',1,1,32,'AGV / 穿梭车 / 堆垛机等自动化设备档案、物流任务下发与操作日志。','2026-09-21 08:41:56.689277','2026-09-22 06:47:20.212818',NULL),(20,'ehs_admin','安全环保管理员','company',1,1,33,'安全制度与培训、隐患排查、应急预案、事故处理、环保台账、消防与设备设施安全。','2026-09-21 08:41:56.694477','2026-09-22 06:47:20.216355',NULL),(21,'iot_admin','设备数采管理员','company',1,1,34,'数采连接、数采设备与采集测点维护，设备令牌下发，采集读数与日志查询；只读采集，不下发控制逻辑。','2026-09-21 09:38:08.693170','2026-09-22 06:47:20.220011',NULL),(22,'production_manager','生产管理员','company',1,1,30,'生产工单下达、领料、报工、完工与完工入库；质检点检验单由质检角色判定，生产侧只负责发起。','2026-09-22 06:47:20.199016','2026-09-22 06:47:20.199016',NULL);
