--
-- Table structure for table `iot_iotpoint`
--

DROP TABLE IF EXISTS `iot_iotpoint`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iot_iotpoint` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `code` varchar(32) NOT NULL,
  `name` varchar(64) NOT NULL,
  `quantity` varchar(16) NOT NULL,
  `unit` varchar(16) NOT NULL,
  `range_min` decimal(20,6) DEFAULT NULL,
  `range_max` decimal(20,6) DEFAULT NULL,
  `precision` smallint(5) unsigned NOT NULL,
  `is_cumulative` tinyint(1) NOT NULL,
  `upper_limit` decimal(20,6) DEFAULT NULL,
  `lower_limit` decimal(20,6) DEFAULT NULL,
  `alarm_enabled` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `remark` longtext NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `gateway_id` bigint(20) NOT NULL,
  `meter_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_iot_point_gateway_code` (`company_id`,`gateway_id`,`code`),
  KEY `idx_iot_point_active` (`gateway_id`,`is_active`),
  KEY `iot_iotpoint_created_by_id_cd852663_fk_identity_user_id` (`created_by_id`),
  KEY `iot_iotpoint_meter_id_0f2ca6af_fk_ems_energymeter_id` (`meter_id`),
  KEY `iot_iotpoint_updated_by_id_d500682e_fk_identity_user_id` (`updated_by_id`),
  KEY `iot_iotpoint_created_at_780c305e` (`created_at`),
  KEY `iot_iotpoint_is_active_ea1fcc86` (`is_active`),
  CONSTRAINT `iot_iotpoint_company_id_6fb3e5c6_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `iot_iotpoint_created_by_id_cd852663_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `iot_iotpoint_gateway_id_baeb91f7_fk_iot_iotgateway_id` FOREIGN KEY (`gateway_id`) REFERENCES `iot_iotgateway` (`id`),
  CONSTRAINT `iot_iotpoint_meter_id_0f2ca6af_fk_ems_energymeter_id` FOREIGN KEY (`meter_id`) REFERENCES `ems_energymeter` (`id`),
  CONSTRAINT `iot_iotpoint_updated_by_id_d500682e_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `iot_iotpoint_chk_1` CHECK ((`version` >= 0)),
  CONSTRAINT `iot_iotpoint_chk_2` CHECK ((`precision` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

