--
-- Table structure for table `iot_iotreading`
--

DROP TABLE IF EXISTS `iot_iotreading`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iot_iotreading` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `device_time` datetime(6) NOT NULL,
  `received_at` datetime(6) NOT NULL,
  `value` decimal(20,6) NOT NULL,
  `unit` varchar(16) NOT NULL,
  `quality` varchar(16) NOT NULL,
  `source` varchar(16) NOT NULL,
  `is_simulated` tinyint(1) NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `gateway_id` bigint(20) NOT NULL,
  `message_id` bigint(20) DEFAULT NULL,
  `point_id` bigint(20) NOT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_iot_reading_point_time` (`point_id`,`device_time`),
  KEY `idx_iot_reading_timeline` (`company_id`,`point_id`,`device_time`),
  KEY `idx_iot_reading_received` (`company_id`,`received_at`),
  KEY `iot_iotreading_created_by_id_1fe932da_fk_identity_user_id` (`created_by_id`),
  KEY `iot_iotreading_gateway_id_25043cef_fk_iot_iotgateway_id` (`gateway_id`),
  KEY `iot_iotreading_message_id_4a44f6f3_fk_iot_iotmessage_id` (`message_id`),
  KEY `iot_iotreading_updated_by_id_84faec85_fk_identity_user_id` (`updated_by_id`),
  KEY `iot_iotreading_created_at_5b3e5983` (`created_at`),
  KEY `iot_iotreading_device_time_e6c265dd` (`device_time`),
  KEY `iot_iotreading_received_at_71f6ec4a` (`received_at`),
  KEY `iot_iotreading_is_simulated_6b8d01c2` (`is_simulated`),
  CONSTRAINT `iot_iotreading_company_id_a2955dbc_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `iot_iotreading_created_by_id_1fe932da_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `iot_iotreading_gateway_id_25043cef_fk_iot_iotgateway_id` FOREIGN KEY (`gateway_id`) REFERENCES `iot_iotgateway` (`id`),
  CONSTRAINT `iot_iotreading_message_id_4a44f6f3_fk_iot_iotmessage_id` FOREIGN KEY (`message_id`) REFERENCES `iot_iotmessage` (`id`),
  CONSTRAINT `iot_iotreading_point_id_3d8cabad_fk_iot_iotpoint_id` FOREIGN KEY (`point_id`) REFERENCES `iot_iotpoint` (`id`),
  CONSTRAINT `iot_iotreading_updated_by_id_84faec85_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `iot_iotreading_chk_1` CHECK ((`version` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

