  KEY `logistics_automationdevice_next_maintenance_date_37ff50de` (`next_maintenance_date`),
  KEY `logistics_automationdevice_is_active_0e54fe11` (`is_active`),
  CONSTRAINT `logistics_automation_company_id_1af88de8_fk_factory_c` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `logistics_automation_created_by_id_0f0c120c_fk_identity_` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `logistics_automation_updated_by_id_10882dab_fk_identity_` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
