CREATE TABLE `mes_productionordermaterial` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `line_no` int(10) unsigned NOT NULL,
  `source` varchar(16) NOT NULL,
  `required_quantity` decimal(20,6) NOT NULL,
  `issued_quantity` decimal(20,6) NOT NULL,
  `unit` varchar(16) NOT NULL,
  `remark` varchar(255) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `location_id` bigint(20) DEFAULT NULL,
  `material_id` bigint(20) NOT NULL,
  `order_id` bigint(20) NOT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mes_material_order_line` (`order_id`,`line_no`),
  KEY `mes_productionorderm_created_by_id_1f4ea580_fk_identity_` (`created_by_id`),
  KEY `mes_productionorderm_location_id_6a3e21ea_fk_wms_locat` (`location_id`),
  KEY `mes_productionorderm_material_id_d45fa3e7_fk_masterdat` (`material_id`),
  KEY `mes_productionorderm_updated_by_id_40b2a2bd_fk_identity_` (`updated_by_id`),
  KEY `mes_productionordermaterial_created_at_78158430` (`created_at`),
  CONSTRAINT `mes_productionorderm_created_by_id_1f4ea580_fk_identity_` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `mes_productionorderm_location_id_6a3e21ea_fk_wms_locat` FOREIGN KEY (`location_id`) REFERENCES `wms_location` (`id`),
  CONSTRAINT `mes_productionorderm_material_id_d45fa3e7_fk_masterdat` FOREIGN KEY (`material_id`) REFERENCES `masterdata_material` (`id`),
  CONSTRAINT `mes_productionorderm_order_id_d5ad0cdb_fk_mes_produ` FOREIGN KEY (`order_id`) REFERENCES `mes_productionorder` (`id`),
  CONSTRAINT `mes_productionorderm_updated_by_id_40b2a2bd_fk_identity_` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `ck_mes_material_required_positive` CHECK ((`required_quantity` > 0)),
  CONSTRAINT `mes_productionordermaterial_chk_1` CHECK ((`version` >= 0)),
  CONSTRAINT `mes_productionordermaterial_chk_2` CHECK ((`line_no` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
