INSERT INTO `qms_qualityissue` VALUES (4,'2026-08-13 02:00:00.000000','2026-09-22 06:50:07.554925',0,'KI202609220001','缝制针距密度超差（下摆明线）','craft','major','不合格项目：缝制针距密度、缝口强力','缝纫机针距调节机构松动，操作工未按首件确认换线后参数。','重新校准针距并全批返工返修，返工后逐件复检。','换线换款必须做首件确认，机修每周点检针距机构。','','[]','published','2026-09-22 06:50:07.554925',1,'',5,NULL,NULL,7,43,NULL);
