  `biz_id` varchar(64) NOT NULL,
  `biz_no` varchar(64) NOT NULL,
  `idempotency_key` varchar(128) DEFAULT NULL,
  `posted_at` datetime(6) DEFAULT NULL,
  `reversed_at` datetime(6) DEFAULT NULL,
  `reverse_reason` longtext NOT NULL,
  `remark` longtext NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `posted_by_id` bigint(20) DEFAULT NULL,
  `reversed_by_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  `warehouse_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inventory_document_company_no` (`company_id`,`document_no`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `wms_inventorydocument_created_by_id_2faec7c3_fk_identity_user_id` (`created_by_id`),
  KEY `wms_inventorydocument_posted_by_id_ec480742_fk_identity_user_id` (`posted_by_id`),
  KEY `wms_inventorydocumen_reversed_by_id_5941f5eb_fk_identity_` (`reversed_by_id`),
  KEY `wms_inventorydocument_updated_by_id_f0f5ec1b_fk_identity_user_id` (`updated_by_id`),
  KEY `wms_inventorydocument_warehouse_id_c8b3d7b2_fk_wms_warehouse_id` (`warehouse_id`),
  KEY `wms_inventorydocument_created_at_601b6b69` (`created_at`),
  KEY `wms_inventorydocument_document_type_ce04632c` (`document_type`),
  KEY `wms_inventorydocument_status_23cdb29d` (`status`),
  CONSTRAINT `wms_inventorydocumen_reversed_by_id_5941f5eb_fk_identity_` FOREIGN KEY (`reversed_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `wms_inventorydocument_company_id_7d2094e5_fk_factory_company_id` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `wms_inventorydocument_created_by_id_2faec7c3_fk_identity_user_id` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `wms_inventorydocument_posted_by_id_ec480742_fk_identity_user_id` FOREIGN KEY (`posted_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `wms_inventorydocument_updated_by_id_f0f5ec1b_fk_identity_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `wms_inventorydocument_warehouse_id_c8b3d7b2_fk_wms_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `wms_warehouse` (`id`),
  CONSTRAINT `wms_inventorydocument_chk_1` CHECK ((`version` >= 0))
