  `transaction_type` varchar(16) NOT NULL,
  `batch_no` varchar(64) NOT NULL,
  `roll_no` varchar(64) NOT NULL,
  `quality_status` varchar(16) NOT NULL,
  `dimension_key` varchar(64) NOT NULL,
  `quantity` decimal(20,6) NOT NULL,
  `on_hand_before` decimal(20,6) NOT NULL,
  `on_hand_after` decimal(20,6) NOT NULL,
  `frozen_after` decimal(20,6) NOT NULL,
  `reserved_after` decimal(20,6) NOT NULL,
  `reason` varchar(255) NOT NULL,
  `dedup_key` varchar(191) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `company_id` bigint(20) NOT NULL,
  `document_id` bigint(20) DEFAULT NULL,
  `document_line_id` bigint(20) DEFAULT NULL,
  `location_id` bigint(20) DEFAULT NULL,
  `material_id` bigint(20) NOT NULL,
  `operator_id` bigint(20) DEFAULT NULL,
  `warehouse_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dedup_key` (`dedup_key`),
  KEY `idx_txn_material_wh_id` (`material_id`,`warehouse_id`,`id` DESC),
  KEY `idx_txn_document_id` (`document_id`,`id`),
  KEY `wms_inventorytransac_company_id_abf30439_fk_factory_c` (`company_id`),
