  KEY `wms_inventorytransaction_location_id_d16c0a69_fk_wms_location_id` (`location_id`),
  KEY `wms_inventorytransac_operator_id_b240f145_fk_identity_` (`operator_id`),
  KEY `wms_inventorytransac_warehouse_id_fdf103e6_fk_wms_wareh` (`warehouse_id`),
  KEY `wms_inventorytransaction_transaction_type_49c5799d` (`transaction_type`),
  KEY `wms_inventorytransaction_quality_status_cf2201ae` (`quality_status`),
  KEY `wms_inventorytransaction_dimension_key_c7239224` (`dimension_key`),
  KEY `wms_inventorytransaction_created_at_7dd267a4` (`created_at`),
  CONSTRAINT `wms_inventorytransac_company_id_abf30439_fk_factory_c` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `wms_inventorytransac_document_id_fdbdb0ed_fk_wms_inven` FOREIGN KEY (`document_id`) REFERENCES `wms_inventorydocument` (`id`),
