--
-- Table structure for table `wms_location`
--

DROP TABLE IF EXISTS `wms_location`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wms_location` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `code` varchar(32) NOT NULL,
  `name` varchar(64) NOT NULL,
  `location_type` varchar(16) NOT NULL,
  `row_no` varchar(16) NOT NULL,
  `column_no` varchar(16) NOT NULL,
  `level_no` varchar(16) NOT NULL,
  `capacity` decimal(20,6) DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `remark` longtext NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  `zone_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_location_zone_code` (`zone_id`,`code`),
  KEY `idx_location_zone_active` (`zone_id`,`is_active`),
  KEY `wms_location_created_by_id_79ea020f_fk_identity_user_id` (`created_by_id`),
  KEY `wms_location_updated_by_id_4b07bff5_fk_identity_user_id` (`updated_by_id`),
  KEY `wms_location_created_at_46087d1c` (`created_at`),
