  `status` varchar(16) NOT NULL,
  `current_seq` int(10) unsigned NOT NULL,
  `submitted_at` datetime(6) DEFAULT NULL,
  `finished_at` datetime(6) DEFAULT NULL,
  `applicant_id` bigint(20) NOT NULL,
  `company_id` bigint(20) DEFAULT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `department_id` bigint(20) DEFAULT NULL,
  `updated_by_id` bigint(20) DEFAULT NULL,
  `template_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `workflow_approvalins_template_id_d9c40bdf_fk_workflow_` (`template_id`),
  KEY `idx_approval_status` (`status`,`id` DESC),
  KEY `idx_approval_biz` (`biz_type`,`biz_id`),
  KEY `idx_approval_applicant` (`applicant_id`,`status`),
  KEY `workflow_approvalins_company_id_fd3278d0_fk_factory_c` (`company_id`),
  KEY `workflow_approvalins_created_by_id_3568a143_fk_identity_` (`created_by_id`),
  KEY `workflow_approvalins_department_id_7268c828_fk_factory_d` (`department_id`),
  KEY `workflow_approvalins_updated_by_id_9fb50a80_fk_identity_` (`updated_by_id`),
  KEY `workflow_approvalinstance_created_at_f9d75815` (`created_at`),
  KEY `workflow_approvalinstance_biz_type_17363e89` (`biz_type`),
  KEY `workflow_approvalinstance_biz_id_4f8123b9` (`biz_id`),
  KEY `workflow_approvalinstance_status_6b0e4689` (`status`),
  CONSTRAINT `workflow_approvalins_applicant_id_5a6d3ed0_fk_identity_` FOREIGN KEY (`applicant_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `workflow_approvalins_company_id_fd3278d0_fk_factory_c` FOREIGN KEY (`company_id`) REFERENCES `factory_company` (`id`),
  CONSTRAINT `workflow_approvalins_created_by_id_3568a143_fk_identity_` FOREIGN KEY (`created_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `workflow_approvalins_department_id_7268c828_fk_factory_d` FOREIGN KEY (`department_id`) REFERENCES `factory_department` (`id`),
  CONSTRAINT `workflow_approvalins_template_id_d9c40bdf_fk_workflow_` FOREIGN KEY (`template_id`) REFERENCES `workflow_approvaltemplate` (`id`),
  CONSTRAINT `workflow_approvalins_updated_by_id_9fb50a80_fk_identity_` FOREIGN KEY (`updated_by_id`) REFERENCES `identity_user` (`id`),
  CONSTRAINT `workflow_approvalinstance_chk_1` CHECK ((`version` >= 0)),
  CONSTRAINT `workflow_approvalinstance_chk_2` CHECK ((`template_version` >= 0)),
  CONSTRAINT `workflow_approvalinstance_chk_3` CHECK ((`current_seq` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=145 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
